"""AORC review, the record: builds results/review_aorc_rain_to_midnight.json (the structure of the E1 review: who, when, what, files_reviewed, method, checks, answers, numbers, discrepancies, must_fix,
should_fix, observations, counts, verdict, scripts, not_checked, dates). The text is the reviewer's own and is written in this file; every NUMBER in it is read from the outputs of the other scripts of this folder
($REVIEW_OUT/*.json, made by run_fast_checks.sh and run_slow_checks.sh) or computed here from the project's files, so that the record cannot drift from the checks.
By default it writes $REVIEW_OUT/review_aorc_rain_to_midnight.json and leaves the project alone; only  --write-into-project  writes results/review_aorc_rain_to_midnight.json, and only when every file of
files_reviewed still has the hash of the reviewer's first inventory (a1_integrity.json), and the file passes a strict-JSON round trip. The builder's script 16_aorc_rain_to_midnight.py reads the top-level
`counts` and the `sha256` of the preds/models entries of files_reviewed from the written file."""
import sys; sys.dont_write_bytecode = True
import hashlib, time, glob, math, re
from a_common import *

WRITE = "--write-into-project" in sys.argv
J = lambda n: json.load(open(f"{OUT}/{n}.json"))
R = jload("results/aorc_rain_to_midnight.json")
a1, a2, a3, a4, a5, a5b, a6, a7, a8, a9 = (J(n) for n in ("a1_integrity", "a2_headline", "a3_clocks", "a4_networks", "a5_cache", "a5b_stamp", "a6_check", "a7_hindsight", "a8_hindsight_networks", "a9_byperiod"))
a10r, a10f, a10p, a11, a12, a13, a14 = (J(n) for n in ("a10_ridge", "a10_forest", "a10_perturb", "a11_outcome", "a12_figure", "a13_test_flood", "a14_readings"))
a7a = J("a7a_days")
sha = lambda rel: hashlib.sha256(open(f"{PROJ}/{rel}", "rb").read()).hexdigest()
tf = lambda t: time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(t))
pct = lambda x, d=1: f"{100 * x:.{d}f}%"
pts = lambda x, d=1: f"{100 * x:+.{d}f}"
E = a2["engine"]; own = a2["own"]
hit = lambda n, k=1: own[n][f"l{k}"]["hits"]
pod = lambda n, k=1: own[n][f"l{k}"]["pod"]
nse = lambda n, k=1: E[n][f"l{k}"]["nse_median"]
N_ON = own["lstm_wqa"]["l1"]["n_onsets"]
T1 = a8["T1"]["results"]; T2 = a8["T2"]; T3 = a8["T3"]
REG = a7["regressions"]; reg_all = REG["both (78 days)|A_pre~S_pre+S_post"]; reg_late = REG["both (78 days)|A_late~S_late+S_post"]
reg_b = REG["builder 50 days|A_pre~S_pre+S_post"]; reg_m = REG["my 28 days|A_pre~S_pre+S_post"]; reg_b_late = REG["builder 50 days|A_late~S_late+S_post"]; reg_m_late = REG["my 28 days|A_late~S_late+S_post"]
FAC = a7["factor_model"]; DRY = a7["dry_before_wet_after"]; BP = a9["differences"]; SW = a9["nse_swing_summary"]
DOC_URL = "https://www.weather.gov/media/owp/operations/aorc_v1_1_methods.pdf"

# ---- files_reviewed: path -> sha256, bytes, modified (hashes taken NOW, compared with the first inventory of the review) ---------------------------------------------------------------------------------
first = a1["inventory"]
extra = ["code/review/rain_to_midnight/README.md"]                                                          # not reviewed: listed in scripts only
files_listed = list(first.keys())
files_reviewed, changed = {}, []
for f in files_listed:
    h = sha(f); files_reviewed[f] = dict(sha256=h, bytes=os.path.getsize(f"{PROJ}/{f}"), modified=tf(os.path.getmtime(f"{PROJ}/{f}")))
    if h != first[f]["sha256"]: changed.append(f)
ROLE = {"results/fair_test.json": "read only: compared with the file my redirected run of test_flood.py writes (byte-identical); another agent's run of test_flood.py rewrote it at 21:56:28, the hash is that of the moment this record was written",
        "ROADMAP.md": "read only: the E1b readings paragraph and the 'What to trust' list were compared with the numbers; the file is being edited by another agent (changed at 20:56:47 and 22:09:08), the hash is that of the moment this record was written"}
for f in ("data/aorc/choice.json", "data/aorc/grid_meta.json", "data/aorc/download_runs.json", "data/aorc/drift_check.json", "results/day_windows.json", "results/fair_test.json", "results/baselines.json", "ROADMAP.md"):
    if os.path.exists(f"{PROJ}/{f}") and f not in files_reviewed:
        files_reviewed[f] = dict(sha256=sha(f), bytes=os.path.getsize(f"{PROJ}/{f}"), modified=tf(os.path.getmtime(f"{PROJ}/{f}")), role=ROLE.get(f, "read only"))
print(f"{len(files_reviewed)} files in files_reviewed; {len(changed)} of the first inventory changed since: {changed}")
SAVED = [f for f in files_reviewed if f.startswith(("results/preds/", "results/models/"))]
assert len(SAVED) == 30, len(SAVED)
saved_eq_json = all(R["integrity"]["sha256_of_saved_files"][f] == files_reviewed[f]["sha256"] for f in SAVED)

# ============================================================================================ the checks ============================================================================================
checks = []
def chk(id_, what, how, result, numbers, note=None):
    assert result in ("pass", "finding", "fail")
    d = dict(id=id_, what=what, how=how, result=result, numbers=numbers)
    if note: d["note"] = note
    checks.append(d)

