         lead1={n: dict(nse_median=round(nse(n), 4), hits=hit(n), onsets=N_ON, pod=round(pod(n), 4), far=round(own[n]["l1"]["far"], 4)) for n in ("lstm_wqa", "lstm_wqa_to09", "lstm_wqa_utc", "lstm_wqa_rep", "lstm_wq", "lstm_wqh", "lstm_wqn", "lstm_wqf", "base_linreg_wqa", "base_rf_wqa")},
