chk("a2", "Seed averages equal the mean of the three seed files; observed flow identical across seeds, in the averages, and equal to the project's flow (flood.load_data) for every set and for the two simple models", "own code (a2_headline.py)", "pass",
    dict(seed_average={n: dict(max_abs_diff=v["max_abs_diff"], nan_pattern_equal=v["nan_pattern_equal"], obs_equal_across_seeds=v["obs_equal_across_seeds"]) for n, v in a2["seed_average"].items()}, obs_equal_project_flow=a2["obs_equal_project_flow"], obs_equal_project_flow_simple=a2["obs_equal_project_flow_simple"],
         per_seed_values_equal_json={n: v["max_dev_vs_json"] == 0 for n, v in a2["per_seed"].items()}, onset_pod_by_seed={n: [round(x, 4) for x in v["onset_pod"]] for n, v in a2["per_seed"].items()}, nse_median_by_seed={n: [round(x, 4) for x in v["nse_median"]] for n, v in a2["per_seed"].items()}))
